using PdfSharp.Pdf;using PdfSharp.Pdf.IO;using ProformaViewer.Models;
namespace ProformaViewer.Services;
public sealed record ExportResult(int PageCount,IReadOnlyList<string> Errors);
public sealed class PdfExportService { public Task<ExportResult> ExportAsync(IEnumerable<ProformaEntry> e,string d,IProgress<int>? p=null)=>Task.Run(()=>Export(e,d,p));static ExportResult Export(IEnumerable<ProformaEntry> source,string destination,IProgress<int>? progress){var entries=source.ToList();var errors=new List<string>();using var output=new PdfDocument();var done=0;var total=Math.Max(1,entries.Sum(e=>e.Pages.Count));foreach(var e in entries){if(!System.IO.File.Exists(e.Path)){errors.Add($"{e.Title}: PDF not found: {e.Path}");done+=e.Pages.Count;continue;}try{using var input=PdfReader.Open(e.Path,PdfDocumentOpenMode.Import);foreach(var page in e.Pages){if(page>input.PageCount)errors.Add($"{e.Title}: page {page} exceeds {input.PageCount} pages.");else output.AddPage(input.Pages[page-1]);progress?.Report(++done*100/total);}}catch(Exception ex){errors.Add($"{e.Title}: {ex.Message}");done+=e.Pages.Count;}}var count=output.Pages.Count;if(count==0)throw new InvalidOperationException("No valid pages could be exported."+Environment.NewLine+string.Join(Environment.NewLine,errors));var folder=System.IO.Path.GetDirectoryName(destination);if(!string.IsNullOrWhiteSpace(folder))System.IO.Directory.CreateDirectory(folder);output.Save(destination);progress?.Report(100);return new(count,errors);} }
